import hou, json

node = None
for n in hou.node('/obj').children():
    if n.type().name().startswith('cinema::camera_rig'):
        node = n
        break

if not node:
    result = 'ERROR: node not found'
else:
    ptg = node.parmTemplateGroup()
    custom_tabs = {}
    separators = []
    labels = []

    for pt in ptg.parmTemplates():
        if pt.type() == hou.parmTemplateType.Folder:
            tab = pt.label()
            # Skip default Houdini tabs
            if tab in ('Transform', 'Subnet'):
                continue
            parms_info = []
            for child in pt.parmTemplates():
                ptype = child.type().name()
                pname = child.name()
                if ptype == 'Separator':
                    separators.append(f'{tab}/{pname}')
                    continue
                elif ptype == 'Label':
                    labels.append(f'{tab}/{pname}')
                    continue
                phelp = ''
                try:
                    phelp = child.help()
                except:
                    pass
                parms_info.append({'name': pname, 'help': phelp[:60] + '...' if len(phelp) > 60 else phelp})
            custom_tabs[tab] = parms_info

    # Check effective_squeeze conditional
    eff_pt = node.parm('effective_squeeze')
    cond_str = ''
    if eff_pt:
        pt = eff_pt.parmTemplate()
        conds = pt.conditionals()
        cond_str = str(conds)

    result = json.dumps({
        'tabs': custom_tabs,
        'separators': separators,
        'labels': labels,
        'effective_squeeze_conditionals': cond_str,
    }, indent=2)
"

